<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Przenieś lub kopiuj';?>
<div class="page-head"><div><p class="eyebrow">Strona</p><h1><?=Html::e($page['title'])?></h1></div><a class="button secondary" href="<?=Html::e(Url::to('/pages/'.$page['id']))?>">Wróć</a></div><?php if(isset($_GET['error'])):?><div class="alert danger">Operacja nie została wykonana. Sprawdź uprawnienia i stronę docelową.</div><?php endif;?>
<section class="card section-card"><h2>Przenieś</h2><p class="muted">Przeniesienie obejmuje całe poddrzewo. Backend blokuje cykle i ponownie sprawdza ACL każdej przenoszonej strony.</p><form method="post" action="<?=Html::e(Url::to('/pages/'.$page['id'].'/move'))?>" class="grid compact-form"><?=Csrf::field()?><label>Przestrzeń docelowa<select name="space_id" required><?php foreach($spaces as $s):?><option value="<?=Html::e($s['id'])?>" <?=(int)$s['id']===(int)$page['space_id']?'selected':''?>><?=Html::e($s['name'])?> (<?=Html::e($s['space_key'])?>)</option><?php endforeach;?></select></label><label>ID strony nadrzędnej<input name="parent_id" type="number" min="1" placeholder="puste = root"></label><div class="form-action"><button class="button">Przenieś</button></div></form></section>
<section class="card section-card"><h2>Kopiuj stronę</h2><form method="post" action="<?=Html::e(Url::to('/pages/'.$page['id'].'/copy'))?>" class="grid compact-form"><?=Csrf::field()?><label>Przestrzeń docelowa<select name="space_id" required><?php foreach($spaces as $s):?><option value="<?=Html::e($s['id'])?>"><?=Html::e($s['name'])?> (<?=Html::e($s['space_key'])?>)</option><?php endforeach;?></select></label><label>ID strony nadrzędnej<input name="parent_id" type="number" min="1"></label><div class="form-action"><button class="button secondary">Utwórz kopię</button></div></form></section>
